body:
Found the issue.  I added some logs to see how it is processing ParticleProcessMaterial:

```cpp
Ref<Resource> ShaderBakerExportPlugin::_customize_resource(const Ref<Resource> &p_resource, const String &p_path) {
	RendererRD::MaterialStorage *singleton = RendererRD::MaterialStorage::get_singleton();
	DEV_ASSERT(singleton != nullptr);

	ParticleProcessMaterial *test = Object::cast_to<ParticleProcessMaterial>(*p_resource);

	if (test != nullptr) {
		print_line("Is particle process material");
	}

	Material *material = Object::cast_to<Material>(*p_resource);
	if (material != nullptr) {
		RID material_rid = material->get_rid();
		if (material_rid.is_valid()) {
			RendererRD::MaterialStorage::ShaderData *shader_data = singleton->material_get_shader_data(material_rid);
			if (shader_data != nullptr) {
				Pair<ShaderRD *, RID> shader_version_pair = shader_data->get_native_shader_and_version();
				if (shader_version_pair.first != nullptr) {
					_customize_shader_version(shader_version_pair.first, shader_version_pair.second);
				} else {
					print_line("First pair null on particle process material");
				}
			} else {
				print_line("Shader null on particle process material");
			}
		} else {
			print_line("Material invalid on particle process material");
		}
	} else if (test) {
		print_line("Material null on particle process material");
	}

	return Ref<Resource>();
}
```

Here is the full log: [output.log](https://github.com/user-attachments/files/20370391/output.log)

And here is the piece I think is important:

```
