It looks like it may be because ``shader_data`` is stored in a different struct, with a different type in ``particles_storage.h``:

```cpp
	struct ParticleProcessMaterialData : public MaterialStorage::MaterialData {
		ParticlesShaderData *shader_data = nullptr;
		RID uniform_set;

		virtual void set_render_priority(int p_priority) {}
		virtual void set_next_pass(RID p_pass) {}
		virtual bool update_parameters(const HashMap<StringName, Variant> &p_parameters, bool p_uniform_dirty, bool p_textures_dirty);
		virtual ~ParticleProcessMaterialData();
	};
```

We probably have to cast it like it is done here:

https://github.com/godotengine/godot/blob/4a44078451d746cee2c03af0677a31d97c8d3335/servers/rendering/renderer_rd/storage_rd/particles_storage.cpp#L145C1-L146C112

servers/rendering/renderer_rd/storage_rd/particles_storage.cpp
```cpp
		ParticleProcessMaterialData *md = static_cast<ParticleProcessMaterialData *>(material_storage->material_get_data(particles_shader.default_material, MaterialStorage::SHADER_TYPE_PARTICLES));
		particles_shader.default_shader_rd = particles_shader.shader.version_get_shader(md->shader_data->version, 0);
